WITH filtered AS (SELECT id, session_id, page, duration_sec, LENGTH(event_type) AS event_type_length FROM web_events WHERE event_time < '2024-01-13') SELECT id, duration_sec, event_type_length, AVG(event_type_length) OVER (PARTITION BY page ORDER BY event_type_length, id ROWS BETWEEN 6 PRECEDING AND CURRENT ROW) AS event_type_length_avg_6, AVG(duration_sec) OVER (ORDER BY duration_sec, id ROWS BETWEEN 2 PRECEDING AND 1 PRECEDING) AS duration_sec_avg_2_prior, AVG(duration_sec) OVER (PARTITION BY page) AS page_avg_duration_sec, AVG(duration_sec) OVER (PARTITION BY session_id ORDER BY event_type_length, id ROWS BETWEEN 2 PRECEDING AND 1 PRECEDING) AS duration_sec_avg_2_prior_2, NTILE(4) OVER (ORDER BY event_type_length DESC, id) AS event_type_length_bucket FROM filtered WHERE duration_sec >= 143;
